482	// 新增/未导入数量为非负整数；未导入明细是数组，逐条含正整数数据记录编号与
483	// 非空文本原因；明细条数与未导入数量一致。任一不满足都返回 null，
484	// 不用 0、空数组或 undefined 补造一份成功报告。
485	function parseImportReport(data) {
486	  if (!data || typeof data !== "object" || Array.isArray(data)) return null;
487	  const importedCount = data.imported_count;
488	  const failedCount = data.failed_count;
489	  if (!isNonNegativeInt(importedCount) || !isNonNegativeInt(failedCount)) return null;
490	  if (!Array.isArray(data.failures) || data.failures.length !== failedCount) return null;
491	  const failures = [];
492	  for (const item of data.failures) {
493	    if (!item || typeof item !== "object") return null;
494	    if (typeof item.row !== "number" || !Number.isInteger(item.row) || item.row <= 0) return null;
495	    if (typeof item.reason !== "string" || !item.reason.trim()) return null;
496	    failures.push({row: item.row, reason: item.reason});
497	  }
498	  return {importedCount, failedCount, failures};
499	}
