838	def check_date(value):
839	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
840	    match = DATE_RE.match(value)
841	    if not match:
842	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
843	    try:
844	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
845	    except ValueError:
846	        return False, "重要日期无效（%s）：不是真实日历日期" % value
847	    return True, None
